import json
BASE = "https://freya-bank-final.ahmetkumas-freya.workers.dev/voice/v1/"
CALL = {"type": "object", "properties": {"ani": {"type": "string", "default": ""}, "lang": {"type": "string", "default": "tr"}}}
HDR = {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}, "Accept": {"type": "string", "default": "application/json"}, "Authorization": {"type": "string", "default": "Bearer test"}}}

COMMON = r'''
import json, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
AY = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
def w3(n):
    h = n // 100; t = (n % 100) // 10; o = n % 10; p = []
    if h: p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t: p.append(TENS[t])
    if o: p.append(ONES[o])
    return ' '.join(p)
def words(n):
    n = int(n)
    if n == 0: return 'sıfır'
    p = []
    for val, nm in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        g = n // val
        if g:
            p.append('bin' if (val == 1000 and g == 1) else w3(g) + ' ' + nm)
            n = n % val
    if n: p.append(w3(n))
    return ' '.join(p)
def money(x, cur):
    x = round(float(x) + 0.0000001, 2)
    whole = int(x); sub = int(round((x - whole) * 100))
    if cur == 'TL':
        return words(whole) + ' Türk Lirası' if sub == 0 else words(whole) + ' lira ' + words(sub) + ' kuruş'
    nm = dict(USD='dolar', EUR='euro', GBP='İngiliz Sterlini')[cur]
    sn = 'peni' if cur == 'GBP' else 'sent'
    return words(whole) + ' ' + nm if sub == 0 else words(whole) + ' ' + nm + ' ' + words(sub) + ' ' + sn
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(s):
    d = pdate(s)
    return (str(d.day) + ' ' + AY[d.month] + ' ' + str(d.year)) if d else str(s)
def suffix(s):
    d = pdate(s)
    if not d: return ''
    y = d.year; o = y % 10; t = (y % 100) // 10
    if o: return dict([(1, "'dir"), (2, "'dir"), (3, "'tür"), (4, "'tür"), (5, "'tir"), (6, "'dır"), (7, "'dir"), (8, "'dir"), (9, "'dur")])[o]
    return dict([(0, "'dir"), (1, "'dur"), (2, "'dir"), (3, "'dur"), (4, "'dır"), (5, "'dir"), (6, "'dır"), (7, "'dir"), (8, "'dir"), (9, "'dır")])[t]
def digits(s):
    return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())
def num(v):
    try: return float(v)
    except Exception: return 0.0
'''

SETUP = r'''
import datetime
try:
    now = str(vars.get('now') or '')
    today = datetime.date.fromisoformat(now[:10])
    vars['today'] = today.isoformat()
    vars['call_end'] = 'no'
    vars['setup_state'] = 'ok'
except Exception:
    vars['today'] = ''
    vars['setup_state'] = 'error'
'''

CARDS_POST = COMMON + r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        r = result.get('result') if isinstance(result.get('result'), dict) else dict()
        if not isinstance(d, dict):
            b = result.get('body') if isinstance(result.get('body'), dict) else dict()
            d = b.get('data') if isinstance(b.get('data'), dict) else None
            if isinstance(b.get('result'), dict): r = b.get('result')
        code = str(r.get('returnCode') or r.get('code') or '')
        cards = d.get('cards') if isinstance(d, dict) else None
        if isinstance(cards, list) and len(cards) > 0:
            lines = []; cmap = dict()
            for i, c in enumerate(cards):
                ref = str(i + 1)
                cmap[ref] = str(c.get('cardNumber') or '')
                nm = str(c.get('productName') or '').strip()
                l4 = str(c.get('cardNumberLast4') or '')
                f6 = str(c.get('cardNumber') or '')[:6]
                lines.append('card_ref ' + ref + ': name="' + (nm if nm else '(adı yok: sadece "sonu ' + digits(l4) + ' ile biten kartınız" de)') + '" last4=' + l4 + ' (söyleniş: ' + digits(l4) + ') first6=' + f6 + ' main_card=' + ('evet' if c.get('isMainCard') is not False else 'HAYIR (ek kart, uygun değil)'))
            vars['card_map_json'] = json.dumps(cmap)
            vars['cards_text'] = '\n'.join(lines)
            vars['n_cards'] = str(len(cards))
            vars['cards_state'] = 'ok'
        elif code == 'FB_IVR_CHANNEL_102' or 'CHANNEL_102' in json.dumps(result, ensure_ascii=False):
            vars['cards_state'] = 'none'
        else:
            vars['cards_state'] = 'error'
except Exception:
    vars['cards_state'] = 'error'
'''

EMAIL_POST = r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if not isinstance(d, dict):
            b = result.get('body') if isinstance(result.get('body'), dict) else dict()
            d = b.get('data') if isinstance(b.get('data'), dict) else None
        if isinstance(d, dict) and 'ibanEmail' in d:
            em = str(d.get('ibanEmail') or '').strip()
            if em and str(d.get('communicationType') or '') != 'Phone':
                vars['email_addr'] = em
                local, _, dom = em.partition('@')
                messy = len(local) > 14 or sum(1 for ch in local if ch in '-_.0123456789') > 2
                vars['email_spoken'] = (local[:1] + ' ile başlayan ' + dom.split('.')[0] + ' adresiniz') if messy else em.replace('@', ' et ').replace('.', ' nokta ')
                vars['email_state'] = 'yes'
            else:
                vars['email_state'] = 'none'
        else:
            vars['email_state'] = 'error'
except Exception:
    vars['email_state'] = 'error'
'''

REF_PRE = r'''
import json
try:
    m = json.loads(str(vars.get('card_map_json') or '{}'))
    ref = str(vars.get('card_ref') or '').strip()
    cn = m.get(ref, ref)
    vars['card_ref'] = cn
    vars['cur_card'] = cn
    b = config.get('body') if isinstance(config, dict) else None
    if isinstance(b, dict) and isinstance(b.get('data'), dict):
        b['data']['cardNumber'] = cn
        if 'statementDay' in b['data']:
            try:
                b['data']['statementDay'] = int(str(vars.get('cur_stmt_day') or b['data']['statementDay']))
            except Exception:
                pass
        if 'newStatementWeek' in b['data']:
            try:
                b['data']['newStatementWeek'] = int(str(b['data']['newStatementWeek']).strip().rstrip('.'))
            except Exception:
                pass
except Exception:
    pass
'''

def getd():
    return r'''
    d = result.get('data')
    r = result.get('result') if isinstance(result.get('result'), dict) else dict()
    if not isinstance(d, dict) and isinstance(result.get('body'), dict):
        d = result['body'].get('data'); r = result['body'].get('result') or r
    ok = isinstance(d, dict) and str(r.get('returnCode', '1')) == '1'
    if not isinstance(d, dict):
        d = dict(); result['data'] = d
'''

BAL_POST = COMMON + r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
''' + getd() + r'''
        if not ok or 'statementDate' not in d:
            d['what_to_do_next'] = 'SERVİS HATASI. Müşteriye tam olarak şunu söyle: "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum." ve aynı turda end_call aracını outcome=agent ile çağır.'
        else:
            today = datetime.date.fromisoformat(str(vars.get('today') or '')[:10])
            l4 = str(d.get('cardNumberLast4') or '')
            nm = str(d.get('productName') or '').strip()
            intro = 'Sonu ' + digits(l4) + ' ile biten ' + (nm + ' kartınıza' if nm else 'kartınıza')
            sd = d.get('statementDate'); lp = d.get('lastPayDate')
            vars['last_stmt_date'] = str(sd or '')
            out = []
            nsd = pdate(d.get('nextStatementDate'))
            if nsd == today or pdate(sd) == today:
                out.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
            CUR = [('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')]
            top = str(d.get('statementPaymentStatus') or '')
            tl = d.get('debtTL') if isinstance(d.get('debtTL'), dict) else None
            anydebt = False
            for c, k, n in CUR:
                b = d.get(k)
                if isinstance(b, dict) and num(b.get('remainingDebt')) > 0 and num(b.get('statementDebt')) > 0:
                    anydebt = True
            if top == 'NO_DEBT' or not anydebt or not sd:
                tot = num(tl.get('totalDebt')) if tl else 0.0
                if sd:
                    s = intro.replace('kartınıza', 'kartınızın') + ' ' + sdate(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
                else:
                    s = intro.replace('kartınıza', 'kartınızın') + ' kesilmiş bir ekstresi bulunmadığından ekstre borcunuz bulunmamaktadır.'
                if tot > 0:
                    s += ' Gelecek dönemler dahil toplam borcunuz ' + money(tot, 'TL') + "'dir."
                if lp and sd:
                    s += ' Son ödeme tarihiniz ' + sdate(lp) + ' olacaktır.'
                out.append(s)
                kind = 'nodebt'
            else:
                kind = 'debt'
                pre = intro + ' ait ' + sdate(sd) + ' tarihinde kesilen ekstre '
                first = True
                clear = []
                for c, k, n in CUR[1:]:
                    b = d.get(k)
                    if isinstance(b, dict) and num(b.get('transferAmount')) > 0:
                        out.append(n + ' borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır.')
                for c, k, n in CUR:
                    b = d.get(k)
                    if not isinstance(b, dict) or len(b) == 0:
                        continue
                    sdebt = num(b.get('statementDebt')); mn = num(b.get('minPayment')); rd = num(b.get('remainingDebt')); rm = num(b.get('remainingMinPayment'))
                    if rd <= 0 or sdebt <= 0:
                        clear.append(n); continue
                    if c == 'TL':
                        if rm > 0 and rm >= mn:
                            s = 'Türk Lirası borcunuz ' + money(sdebt, c) + ', ödenmesi gereken minimum tutar ' + money(mn, c) + "'dir."
                        elif rm <= 0:
                            s = 'Türk Lirası borcunuz ' + money(sdebt, c) + ', kalan toplam borcunuz ' + money(rd, c) + "'dir. Minimum ödemenizi yaptığınız için teşekkür ederiz."
                        else:
                            s = 'Türk Lirası borcunuz ' + money(sdebt, c) + ', ödenmesi gereken minimum tutar ' + money(mn, c) + ', kalan toplam borcunuz ' + money(rd, c) + ', kalan minimum ödeme tutarınız ' + money(rm, c) + "'dir."
                    else:
                        s = n + ' borcunuz ' + money(sdebt, c) + ', kalan toplam borcunuz ' + money(rd, c) + ', ödenmesi gereken minimum tutar ' + money(mn, c) + "'dir."
                    if first:
                        s = pre + s[0].lower() + s[1:] if not s.startswith('Türk') and not s.startswith('Dolar') and not s.startswith('Euro') and not s.startswith('İngiliz') else pre + s
                        first = False
                    out.append(s)
                if clear:
                    if len(clear) == 1: out.append(clear[0] + ' borcunuz bulunmamaktadır.')
                    else: out.append(', '.join(clear[:-1]) + ' ve ' + clear[-1] + ' borcunuz bulunmamaktadır.')
                lpd = pdate(lp)
                if lpd and lpd < today:
                    if str(d.get('automaticPaymentFlag')) == 'Y' and tl and num(tl.get('remainAutomaticPaymentAmount')) > 0:
