                    s = 'Son ödeme tarihiniz olan ' + sdate(lp) + ' geçmiştir.'
                    tparts = []
                    for c, k, n in CUR:
                        b = d.get(k)
                        if isinstance(b, dict) and num(b.get('totalDebt')) > 0:
                            tparts.append(money(num(b.get('totalDebt')), c))
                    if tparts:
                        s += ' Güncel toplam borcunuz ' + ' ve '.join(tparts) + "'dir."
