            d['what_to_do_next'] = 'Müşteri tüm borcu sorduysa READING metnini KELİMESİ KELİMESİNE oku (rakam ekleme, değiştirme). Sadece tek bir bilgi istediyse (sadece minimum, sadece son ödeme tarihi) SINGLE_FIGURES içinden yalnız onu söyle. Sonra kurala göre devam et (birden fazla kart varsa "Başka bir kartınızın borcunu öğrenmek ister misiniz?", yoksa teklif).'
except Exception as e:
    try:
        result['data'] = dict(what_to_do_next='SERVİS HATASI. "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum." de ve end_call outcome=agent çağır.')
    except Exception:
        pass
'''

WEEKERR = 'SERVİS HATASI. Müşteriye tam olarak "Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum." de ve aynı turda end_call aracını outcome=agent ile çağır.'

WGET_POST = COMMON + r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
''' + getd() + r'''
        if not ok or 'statementWeek' not in d:
            d['what_to_do_next'] = "''' + WEEKERR + r'''"
        else:
            vars['cur_stmt_day'] = str(d.get('statementDay'))
            vars['cur_week'] = str(d.get('statementWeek'))
            wk = int(d.get('statementWeek'))
            others = [str(x) for x in (1, 2, 3, 4) if x != wk]
            d['OPTIONS_SENTENCE'] = 'Hesap kesim tarihinizi ayın ' + others[0] + '., ' + others[1] + '. ya da ' + others[2] + '. haftasına alabilirim. Hangisini tercih edersiniz?'
            d['ALLOWED_WEEKS'] = ', '.join(others)
            nm = str(d.get('productName') or '').strip()
            l4 = str(d.get('cardNumberLast4') or '')
            info = (nm if nm else 'Sonu ' + digits(l4) + ' ile biten') + ' kartınızın hesap kesim tarihi her ayın ' + str(wk) + '. haftası olarak tanımlı. Bir sonraki hesap kesim tarihiniz ' + sdate(d.get('nextStatementDate')) + ', son ödeme tarihiniz ' + sdate(d.get('nextLastPayDate')) + '.'
            rel = str(d.get('relationType') or '')
            rn = str(d.get('relatedCardProductName') or '').strip()
            rl4 = str(d.get('relatedCardNumber') or '')[-4:]
            if rel in ('M', 'C'):
                info = 'Sonu ' + digits(l4) + ' ile biten ' + nm + ' kartınız ile sonu ' + digits(rl4) + ' ile biten ' + rn + ' kartınız ortak ekstreye sahiptir. ' + info + ' Bağlı kartınız da aynı hesap kesim haftasını ve tarihlerini kullanır.'
                d['JOINT_WARNING'] = ('Bu değişiklik kartınıza bağlı ' + rn + ' kartınızı da etkileyecek.') if rel == 'M' else ('Bu değişiklik kartınızın bağlı olduğu ' + rn + ' kartınızı da etkileyecek.')
            else:
                d['JOINT_WARNING'] = ''
            d['INFO_SENTENCE'] = info + ' Hesap kesim tarihinizi değiştirmek ister misiniz?'
            vars['joint_warning'] = d['JOINT_WARNING']
            vars['wk_card_name'] = nm
            vars['wk_last4'] = digits(l4)
            d['what_to_do_next'] = 'INFO_SENTENCE metnini aynen söyle. Evet derse OPTIONS_SENTENCE metnini aynen söyle. Sadece ALLOWED_WEEKS içindeki haftalar seçilebilir.'
except Exception:
    pass
'''

WDEC_POST = COMMON + r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
''' + getd() + r'''
        if not ok or 'statementDate' not in d:
            d['what_to_do_next'] = "''' + WEEKERR + r'''"
        else:
            vars['prev_sd'] = sdate(d.get('statementDate'))
            vars['prev_dd'] = sdate(d.get('statementDueDate'))
            jw = str(vars.get('joint_warning') or '')
            d['CONFIRM_SENTENCE'] = (jw + ' ' if jw else '') + 'Yeni hesap kesim haftanız her ayın ' + str(vars.get('chosen_week') or '') + '. haftası olacak. Yeni hesap kesim tarihiniz ' + vars['prev_sd'] + ', son ödeme tarihiniz ' + vars['prev_dd'] + ' olacak. Onaylıyor musunuz?'
            d['what_to_do_next'] = 'Bu sadece önizleme, HİÇBİR ŞEY DEĞİŞMEDİ. CONFIRM_SENTENCE metnini aynen söyle. Sadece net bir "evet" gelirse statement_week_change çağır. Hayır derse "Sizi ana menüye yönlendiriyorum." de ve end_call outcome=main_menu.'
except Exception:
