p='work/final/gen/build.py'
s=open(p).read()
old=s[s.index("REF_PRE = r'''"):s.index("def getd():")]
new = r"""REF_PRE = r'''
import json
try:
    m = json.loads(str(vars.get('card_map_json') or '{}'))
    b = config.get('body') if isinstance(config, dict) else None
    cands = []
    if isinstance(b, dict) and isinstance(b.get('data'), dict):
        cands.append(str(b['data'].get('cardNumber') or ''))
    cands.append(str(vars.get('card_ref') or ''))
    cn = ''
    for ref in cands:
        ref = ref.strip()
        if not ref or '{' in ref:
            continue
        if ref in m:
            cn = m[ref]; break
        if '*' in ref:
            cn = ref; break
        dg = ''.join(ch for ch in ref if ch.isdigit())
        hits = [v for v in m.values() if dg and len(dg) >= 4 and v.endswith(dg[-4:]) and (len(dg) < 10 or v.startswith(dg[:6]))]
        if len(hits) == 1:
            cn = hits[0]; break
    if not cn and len(m) == 1:
        cn = list(m.values())[0]
    if not cn:
        cn = str(vars.get('cur_card') or '')
    vars['card_ref'] = cn
    vars['cur_card'] = cn
    if isinstance(b, dict) and isinstance(b.get('data'), dict):
        b['data']['cardNumber'] = cn
        if 'statementDay' in b['data']:
            try:
                b['data']['statementDay'] = int(str(vars.get('cur_stmt_day') or b['data']['statementDay']))
            except Exception:
                pass
        if 'newStatementWeek' in b['data']:
            try:
                wk = int(str(b['data']['newStatementWeek']).strip().rstrip('.'))
                b['data']['newStatementWeek'] = wk
                vars['chosen_week'] = str(wk)
            except Exception:
                pass
except Exception:
    pass
'''

"""
s=s.replace(old,new)
s=s.replace('"on_enter": {"type": "tts", "text": "Merhaba, Freya Bank kredi kartı ekstre borcunuzla ilgili size yardımcı olacağım."}','"on_enter": {"type": "silent"}')
open(p,'w').write(s)
EOF
